-- Glacier HMS: run this whole file in a Snowflake worksheet (role with CREATE DATABASE rights)
CREATE WAREHOUSE IF NOT EXISTS HMS_WH WAREHOUSE_SIZE='XSMALL' AUTO_SUSPEND=60 AUTO_RESUME=TRUE;
CREATE DATABASE IF NOT EXISTS HOSPITAL_DB;
CREATE SCHEMA IF NOT EXISTS HOSPITAL_DB.HMS;
USE WAREHOUSE HMS_WH; USE SCHEMA HOSPITAL_DB.HMS;

CREATE TABLE IF NOT EXISTS PATIENTS (ID NUMBER AUTOINCREMENT PRIMARY KEY, NAME VARCHAR NOT NULL, AGE NUMBER, GENDER VARCHAR, PHONE VARCHAR, BLOOD_GROUP VARCHAR, EMAIL VARCHAR, CREATED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE IF NOT EXISTS DOCTORS (ID NUMBER AUTOINCREMENT PRIMARY KEY, NAME VARCHAR NOT NULL, SPECIALTY VARCHAR, PHONE VARCHAR, EMAIL VARCHAR, FEE NUMBER(10,2), AVAILABLE BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS APPOINTMENTS (ID NUMBER AUTOINCREMENT PRIMARY KEY, PATIENT_ID NUMBER NOT NULL REFERENCES PATIENTS(ID), DOCTOR_ID NUMBER NOT NULL REFERENCES DOCTORS(ID), APPT_DATE DATE NOT NULL, APPT_TIME VARCHAR(5), REASON VARCHAR, STATUS VARCHAR DEFAULT 'Scheduled');
CREATE TABLE IF NOT EXISTS BILLS (ID NUMBER AUTOINCREMENT PRIMARY KEY, PATIENT_ID NUMBER NOT NULL REFERENCES PATIENTS(ID), DESCRIPTION VARCHAR, AMOUNT NUMBER(10,2) NOT NULL, STATUS VARCHAR DEFAULT 'Pending', ISSUED_ON DATE DEFAULT CURRENT_DATE());
CREATE TABLE IF NOT EXISTS RECORDS (ID NUMBER AUTOINCREMENT PRIMARY KEY, PATIENT_ID NUMBER NOT NULL REFERENCES PATIENTS(ID), DOCTOR_ID NUMBER REFERENCES DOCTORS(ID), DIAGNOSIS VARCHAR, TREATMENT VARCHAR, NOTES VARCHAR, RECORDED_ON DATE DEFAULT CURRENT_DATE());
CREATE TABLE IF NOT EXISTS USERS (ID NUMBER AUTOINCREMENT PRIMARY KEY, EMAIL VARCHAR UNIQUE NOT NULL, PASSWORD_HASH VARCHAR NOT NULL, ROLE VARCHAR NOT NULL, REF_ID NUMBER);

-- Analytics views used by the dashboard
CREATE OR REPLACE VIEW V_MONTHLY_REVENUE AS SELECT TO_VARCHAR(DATE_TRUNC('month',ISSUED_ON),'YYYY-MM') MONTH, SUM(AMOUNT) REVENUE FROM BILLS WHERE STATUS='Paid' GROUP BY 1;
CREATE OR REPLACE VIEW V_APPT_STATUS AS SELECT STATUS, COUNT(*) TOTAL FROM APPOINTMENTS GROUP BY STATUS;
CREATE OR REPLACE VIEW V_DOCTOR_LOAD AS SELECT d.NAME DOCTOR, COUNT(a.ID) APPOINTMENTS FROM DOCTORS d LEFT JOIN APPOINTMENTS a ON a.DOCTOR_ID=d.ID GROUP BY d.NAME;

